fast_pseudocode:
# After: 128 regs/thread, 25% occupancy, but massive spill to DRAM
@triton.autotune(configs=[
    triton.Config({}, num_warps=4, num_stages=2, maxnreg=128),
    triton.Config({}, num_warps=8, num_stages=2, maxnreg=128),
    triton.Config({}, num_warps=4, num_stages=2, maxnreg=64),
], key=[])
def kernel(...):
    acc = tl.zeros([BLOCK_M, BLOCK_N])  # 128x128 = 16384 FP32, now spills to L2/DRAM
    for k in range(K // BLOCK_K):
        a = tl.load(A + ...)
        b = tl.load(B + ...)
        acc += tl.dot(a, b)
